command:
cat > src/duration.mjs <<'EOF'
import ms from "ms";

export function toMs(text) {
  const value = typeof text === "string" && text !== "" ? ms(text) : undefined;
  if (value === undefined) throw new TypeError(`Not a duration: ${String(text)}`);
  return value;
}
EOF
cat > tests/duration.test.mjs <<'EOF'
import assert from "node:assert/strict";
import { test } from "node:test";
import { toMs } from "../src/duration.mjs";

test("toMs converts durations", () => {
  assert.equal(toMs("2s"), 2000);
  assert.equal(toMs("1h"), 3600000);
  assert.equal(toMs("0s"), 0);
  assert.equal(toMs("1.5s"), 1500);
});

test("toMs rejects non-durations with TypeError", () => {
  for (const bad of ["soon", "2 parsecs", "", 5, null, undefined, {}]) {
    assert.throws(() => toMs(bad), TypeError);
  }
});
EOF
